def posRewardCatalogItems_sp(json_file: dict):
    conn = None
    cursor = None
    try:
        conn = connection()
        cursor = conn.cursor()
        # Capture before-image for audit if it's an UPDATE/DELETE
        action = json_file.get('action')
        if action in [2, 3] and json_file.get('catalogItemId') and json_file.get('companyId'):
            # Fetch before-image using the 'one' SP
            before_image_json = one_posRewardCatalogItems_sp({
                "companyId": json_file['companyId'],
                "catalogItemId": json_file['catalogItemId']
            })
            # one_posRewardCatalogItems_sp returns JSONResponse, so load content
            before_data = json.loads(before_image_json.body.decode('utf-8')).get('posRewardCatalogItems', [{}])[0]
        else:
            before_data = {}

        cursor.execute("EXEC [dbo].[sp_posRewardCatalogItems] @pjsonfile = %s", (json.dumps(json_file),))
        # Upsert SP returns ONE row, ONE column -- use fetchone()[0]
        row = cursor.fetchone()
        json_result = row[0] if row and row[0] else '{"message": "ok"}'
        result = json.loads(json_result)

        # Emit audit logs for meaningful fields on INSERT (action=1) or UPDATE (action=2)
        if action in [1, 2] and result.get('catalogItemId'):
            current_data = result.get('posRewardCatalogItems', [{}])[0] if isinstance(result.get('posRewardCatalogItems'), list) else result # SP might return root obj or array
            # Map SP result to a dict, if the SP returns the inserted/updated record
            audit_fields = [
                ("name", current_data.get("name"), before_data.get("name")),
                ("rewardType", current_data.get("rewardType"), before_data.get("rewardType")),
                ("requiredPoints", current_data.get("requiredPoints"), before_data.get("requiredPoints")),
                ("discountValue", current_data.get("discountValue"), before_data.get("discountValue")),
                ("freeProductId", current_data.get("freeProductId"), before_data.get("freeProductId")),
                ("isActive", current_data.get("isActive"), before_data.get("isActive")),
                ("description", current_data.get("description"), before_data.get("description"))
            ]
            for field, new_val, old_val in audit_fields:
                # Only log if value changed or if it's an INSERT and value exists
                if (action == 1 and new_val is not None) or (action == 2 and new_val != old_val):
                    log_audit(
                        entity="posRewardCatalogItem",
                        entity_id=current_data['catalogItemId'],
                        field=field,
                        old_value=str(old_val) if old_val is not None else None,
                        new_value=str(new_val) if new_val is not None else None,
                        action=action
                    )
        elif action == 3 and before_data.get('catalogItemId'): # DELETE
            log_audit(
                entity="posRewardCatalogItem",
                entity_id=before_data['catalogItemId'],
                field="status",
                old_value="active",
                new_value="deleted",
                action=action
            )

        return JSONResponse(content=result, status_code=200)
    except Exception as e:
        return JSONResponse(content={"error": str(e)}, status_code=500)
    finally:
        try:
            if cursor: cursor.close()
        except Exception: pass
        try:
            if conn: conn.close()
        except Exception: pass


