export interface PosRewardCatalogItem {
  catalogItemId: number;
  companyId: number;
  name: string;
  rewardType: 'discount' | 'free_product';
  requiredPoints: number;
  discountValue: number | null;
  freeProductId: number | null;
  isActive: boolean;
  description: string | null;
  created_At: string;
  updated_at: string | null;
}

export interface PosRewardCatalogItemListResponse {
  posRewardCatalogItems: PosRewardCatalogItem[];
}

// GET ALL — POST /all_posRewardCatalogItems
export async function getAllPosRewardCatalogItems(companyId: number): Promise<PosRewardCatalogItem[]> {
  const res = await fetch(BASE_URL + "/all_posRewardCatalogItems", {
    method: "POST", headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ "posRewardCatalogItems": [{ "companyId": companyId }] }),
  });
  if (!res.ok) throw new Error(await res.text());
  const data: PosRewardCatalogItemListResponse = await res.json();
  return data.posRewardCatalogItems ?? [];
}

// CREATE — action: 1
export async function createPosRewardCatalogItem(payload: Omit<PosRewardCatalogItem, "catalogItemId" | "created_At" | "updated_at">): Promise<PosRewardCatalogItem> {
  const res = await fetch(BASE_URL + "/posRewardCatalogItems", {
    method: "POST", headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ "posRewardCatalogItems": [{ "action": 1, ...payload }] }),
  });
  if (!res.ok) throw new Error(await res.text());
  const result = await res.json();
  return result.posRewardCatalogItems ? result.posRewardCatalogItems[0] : result; // Backend can return root object or array under plural key
}

// UPDATE — action: 2
export async function updatePosRewardCatalogItem(id: number, payload: Partial<Omit<PosRewardCatalogItem, "created_At" | "updated_at" | "companyId" | "catalogItemId"> & { companyId: number }>): Promise<PosRewardCatalogItem> {
  const res = await fetch(BASE_URL + "/posRewardCatalogItems", {
    method: "POST", headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ "posRewardCatalogItems": [{ "action": 2, "catalogItemId": id, ...payload }] }),
  });
  if (!res.ok) throw new Error(await res.text());
  const result = await res.json();
  return result.posRewardCatalogItems ? result.posRewardCatalogItems[0] : result;
}

// DELETE — action: 3
export async function deletePosRewardCatalogItem(id: number, companyId: number): Promise<void> {
  const res = await fetch(BASE_URL + "/posRewardCatalogItems", {
    method: "POST", headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ "posRewardCatalogItems": [{ "action": 3, "catalogItemId": id, "companyId": companyId }] }),
  });
  if (!res.ok) throw new Error(await res.text());
}
