  IonItemOption,
  IonAlert,
  IonInfiniteScroll,
  IonInfiniteScrollContent
} from '@ionic/react';
import { addOutline, createOutline, trashOutline, cashOutline, cubeOutline } from 'ionicons/icons';
import { useUser } from '../contexts/UserContext';
import Header from '../components/Header';
import AlertPopover from '../components/PopOver/AlertPopover';
import MailPopover from '../components/PopOver/MailPopover';
import {
  getAllPosRewardCatalogItems,
  createPosRewardCatalogItem,
  updatePosRewardCatalogItem,
  deletePosRewardCatalogItem,
  PosRewardCatalogItem
} from '../api/posRewardCatalogItemApi';
import { useIonViewWillEnter } from '@ionic/react';
import { InputInputEventDetail, SelectChangeEventDetail, SearchbarInputEventDetail, ToggleChangeEventDetail, TextareaInputEventDetail } from '@ionic/core';

const toHermosillo = (utc: string | undefined | null): string => {
  if (!utc) return '';
  const d = new Date(utc.includes('Z') ? utc : utc + 'Z');
  return new Date(d.getTime() - 7 * 60 * 60 * 1000).toLocaleString();
};

const PosRewardCatalogItemPage: React.FC = () => {
  const { companyId } = useUser();
  const [rewards, setRewards] = useState<PosRewardCatalogItem[]>([]);
  const [displayedRewards, setDisplayedRewards] = useState<PosRewardCatalogItem[]>([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');
  const [searchTerm, setSearchTerm] = useState('');
  const [showModal, setShowModal] = useState(false);
  const [isEditing, setIsEditing] = useState(false);
  const [currentReward, setCurrentReward] = useState<PosRewardCatalogItem | null>(null);
  const [formState, setFormState] = useState<Omit<PosRewardCatalogItem, 'catalogItemId' | 'created_At' | 'updated_at'>>({
    companyId: companyId,
    name: '',
    rewardType: 'discount', // Default
    requiredPoints: 0,
    discountValue: null,
    freeProductId: null,
    isActive: true,
    description: null,
  });
  const [formErrors, setFormErrors] = useState<{ [key: string]: string | null }>({});
  const [confirmDeleteAlert, setConfirmDeleteAlert] = useState(false);
  const [deleteItemId, setDeleteItemId] = useState<number | null>(null);

  const PAGE_SIZE = 20;
  const [page, setPage] = useState(1);

  const [popoverState, setPopoverState] = useState<{ 
    showAlertPopover: boolean; 
    showMailPopover: boolean; 
    event?: Event; 
  }>({ showAlertPopover: false, showMailPopover: false });

  const presentAlertPopover = (e: React.MouseEvent) =>
    setPopoverState({ ...popoverState, showAlertPopover: true, event: e.nativeEvent });
  const dismissAlertPopover = () =>
    setPopoverState({ ...popoverState, showAlertPopover: false });
  const presentMailPopover = (e: React.MouseEvent) =>
    setPopoverState({ ...popoverState, showMailPopover: true, event: e.nativeEvent });
  const dismissMailPopover = () =>
    setPopoverState({ ...popoverState, showMailPopover: false });

  useEffect(() => {
    if (companyId) {
      fetchRewards();
    }
  }, [companyId]);

  useIonViewWillEnter(() => {
    if (companyId) {
      fetchRewards();
    }
  });

  useEffect(() => {
    setDisplayedRewards(rewards.slice(0, PAGE_SIZE));
    setPage(1);
  }, [rewards]);

  const fetchRewards = async () => {
    if (!companyId) return;
    setLoading(true);
    try {
      const data = await getAllPosRewardCatalogItems(companyId);
      setRewards(data);
    } catch (err) {
      setError((err as Error).message ?? 'Error al cargar recompensas.');
    }
    setLoading(false);
  };

  const loadMoreItems = (ev: CustomEvent<void>) => {
    const newPage = page + 1;
    const newItems = rewards.slice(0, newPage * PAGE_SIZE);
    setDisplayedRewards(newItems);
    setPage(newPage);
    (ev.target as HTMLIonInfiniteScrollElement).complete();
  };

  const validateForm = () => {
    let errors: { [key: string]: string | null } = {};
    if (!formState.name) errors.name = 'El nombre es requerido.';
    if (!formState.rewardType) errors.rewardType = 'El tipo de recompensa es requerido.';
    if (formState.requiredPoints === null || formState.requiredPoints <= 0) errors.requiredPoints = 'Los puntos requeridos deben ser mayores a 0.';

    if (formState.rewardType === 'discount') {
      if (formState.discountValue === null || formState.discountValue <= 0) errors.discountValue = 'El valor de descuento es requerido y debe ser mayor a 0.';
    } else if (formState.rewardType === 'free_product') {
      if (formState.freeProductId === null || formState.freeProductId <= 0) errors.freeProductId = 'El ID del producto es requerido y debe ser mayor a 0.';
    }

    setFormErrors(errors);
    return Object.keys(errors).length === 0;
  };

  const handleSave = async () => {
    if (!companyId) {
      setError('Company ID no encontrado.');
      return;
    }
    if (!validateForm()) return;

    setLoading(true);
    try {
      const payload = {
        ...formState,
        companyId: companyId,
        requiredPoints: Number(formState.requiredPoints),
        discountValue: formState.rewardType === 'discount' ? Number(formState.discountValue) : null,
        freeProductId: formState.rewardType === 'free_product' ? Number(formState.freeProductId) : null,
        description: formState.description === '' ? null : formState.description, // Ensure empty string becomes null
      };

      if (isEditing && currentReward) {
        await updatePosRewardCatalogItem(currentReward.catalogItemId, { ...payload, companyId: companyId });
        setError('Recompensa actualizada exitosamente.');
      } else {
        await createPosRewardCatalogItem(payload);
        setError('Recompensa creada exitosamente.');
      }
      setShowModal(false);
      fetchRewards(); // Refresh list
    } catch (err) {
      setError((err as Error).message ?? 'Error al guardar la recompensa.');
    } finally {
      setLoading(false);
    }
  };

  const handleDelete = async () => {
    if (!deleteItemId || !companyId) return;
    setLoading(true);
    try {
      await deletePosRewardCatalogItem(deleteItemId, companyId);
      setError('Recompensa eliminada exitosamente.');
      fetchRewards();
    } catch (err) {
      setError((err as Error).message ?? 'Error al eliminar la recompensa.');
    } finally {
      setLoading(false);
      setDeleteItemId(null);
      setConfirmDeleteAlert(false);
    }
  };

  const handleToggleActive = async (catalogItemId: number, isActive: boolean) => {
    if (!companyId) return;
    setLoading(true);
    try {
      await updatePosRewardCatalogItem(catalogItemId, { isActive: isActive, companyId: companyId });
      setRewards(prevRewards =>
        prevRewards.map(reward =>
          reward.catalogItemId === catalogItemId ? { ...reward, isActive: isActive } : reward
        )
      );
      setError('Estado de recompensa actualizado exitosamente.');
    } catch (err) {
      setError((err as Error).message ?? 'Error al actualizar el estado.');
    } finally {
      setLoading(false);
    }
  };

  const openCreateModal = () => {
    setIsEditing(false);
    setCurrentReward(null);
    setFormState({
      companyId: companyId,
      name: '',
      rewardType: 'discount',
      requiredPoints: 0,
      discountValue: null,
      freeProductId: null,
      isActive: true,
      description: null,
    });
    setFormErrors({});
    setShowModal(true);
  };

  const openEditModal = (reward: PosRewardCatalogItem) => {
    setIsEditing(true);
    setCurrentReward(reward);
    setFormState({
      companyId: reward.companyId,
      name: reward.name,
      rewardType: reward.rewardType,
      requiredPoints: reward.requiredPoints,
      discountValue: reward.discountValue,
      freeProductId: reward.freeProductId,
      isActive: reward.isActive,
      description: reward.description,
    });
    setFormErrors({});
    setShowModal(true);
  };

  const filteredRewards = displayedRewards
    .filter(reward => reward.name.toLowerCase().includes(searchTerm.toLowerCase()));

  return (
    <IonPage className="posrewardcatalogitem-page">
      <Header
        presentAlertPopover={presentAlertPopover}
        presentMailPopover={presentMailPopover}
        screenTitle="Recompensas POS — POS GMO"
      />
      <AlertPopover
        isOpen={popoverState.showAlertPopover}
        event={popoverState.event}
        onDidDismiss={dismissAlertPopover}
      />
      <MailPopover
        isOpen={popoverState.showMailPopover}
        event={popoverState.event}
        onDidDismiss={dismissMailPopover}
      />

      <IonContent className="ion-padding">
        <div className="posrewardcatalogitem-header-actions">
          <IonSearchbar
            value={searchTerm}
            onIonInput={(e: CustomEvent<SearchbarInputEventDetail>) => setSearchTerm(e.detail.value!)}
            placeholder="Buscar recompensa..."
            debounce={300}
          />
          <IonButton expand="block" onClick={openCreateModal}>
            <IonIcon icon={addOutline} slot="start" />
            Nueva Recompensa
          </IonButton>
        </div>

        {loading && rewards.length === 0 ? (
          <div className="ion-text-center ion-padding-top">
            <IonSpinner name="crescent" />
          </div>
        ) : (
          <IonList className="posrewardcatalogitem-list">
            {filteredRewards.map((reward) => (
              <IonItemSliding key={reward.catalogItemId}>
                <IonItemOptions side="end">
                  <IonItemOption color="primary" onClick={() => openEditModal(reward)}>
                    <IonIcon slot="icon-only" icon={createOutline} />
                  </IonItemOption>
                  <IonItemOption color="danger" onClick={() => { setDeleteItemId(reward.catalogItemId); setConfirmDeleteAlert(true); }}>
                    <IonIcon slot="icon-only" icon={trashOutline} />
                  </IonItemOption>
                </IonItemOptions>

                <IonItem>
                  <IonLabel className="posrewardcatalogitem-item-label">
                    <h2>{reward.name}</h2>
                    <p>Puntos requeridos: <strong>{reward.requiredPoints.toFixed(2)}</strong></p>
                    <IonText className="posrewardcatalogitem-description">
                      {reward.description || 'Sin descripción'}
                    </IonText>
                    <div className="posrewardcatalogitem-meta">
                      <IonBadge className={`reward-type-badge type-${reward.rewardType}`}>
                        {reward.rewardType === 'discount' ? 'Descuento' : 'Producto Gratis'}
                      </IonBadge>
                      {reward.rewardType === 'discount' && reward.discountValue !== null && ( 
                        <IonText color="medium">Valor: ${reward.discountValue.toFixed(2)}</IonText>
                      )}
                      {reward.rewardType === 'free_product' && reward.freeProductId && ( 
                        <IonText color="medium">Producto ID: {reward.freeProductId}</IonText>
                      )}
                      <IonText color="medium">
                        Creado: {toHermosillo(reward.created_At)}
                      </IonText>
                    </div>
                  </IonLabel>
                  <IonToggle
                    slot="end"
                    checked={reward.isActive}
                    onIonChange={(e: CustomEvent<ToggleChangeEventDetail>) => handleToggleActive(reward.catalogItemId, e.detail.checked)}
                    aria-label="Activar/Desactivar recompensa"
                  />
                </IonItem>
              </IonItemSliding>
            ))}
            {filteredRewards.length === 0 && searchTerm && !loading && ( 
              <IonItem>
                <IonLabel>No se encontraron recompensas.</IonLabel>
              </IonItem>
            )}
            {filteredRewards.length === 0 && !searchTerm && !loading && ( 
              <IonItem>
                <IonLabel>No hay recompensas disponibles. ¡Crea una nueva!</IonLabel>
              </IonItem>
            )}
          </IonList>
        )}

        {displayedRewards.length < rewards.length && (
