            <div className="wizard-form-fields">
              <div className="wizard-field-group">
                <IonInput
                  fill="outline"
                  label="Nombre de la Recompensa *"
                  labelPlacement="floating"
                  value={formState.name}
                  onIonInput={(e: CustomEvent<InputInputEventDetail>) => setFormState(p => ({ ...p, name: e.detail.value! }))}
                  className={formErrors.name ? 'ion-invalid ion-touched' : ''}
                  errorText={formErrors.name}
                />
              </div>

              <div className="wizard-field-group">
                <IonSelect
                  fill="outline"
                  label="Tipo de Recompensa *"
                  labelPlacement="floating"
                  value={formState.rewardType}
                  onIonChange={(e: CustomEvent<SelectChangeEventDetail>) => {
                    const newType = e.detail.value!;
                    setFormState(p => ({ ...p, rewardType: newType, discountValue: null, freeProductId: null }));
                  }}
                  className={formErrors.rewardType ? 'ion-invalid ion-touched' : ''}
                  errorText={formErrors.rewardType}
                >
                  <IonSelectOption value="discount">Descuento</IonSelectOption>
                  <IonSelectOption value="free_product">Producto Gratis</IonSelectOption>
                </IonSelect>
              </div>

              <div className="wizard-field-group">
                <IonInput
                  fill="outline"
                  label="Puntos Requeridos *"
                  labelPlacement="floating"
                  type="number"
                  value={formState.requiredPoints === 0 ? '' : formState.requiredPoints.toString()}
                  onIonInput={(e: CustomEvent<InputInputEventDetail>) => setFormState(p => ({ ...p, requiredPoints: parseFloat(e.detail.value!) || 0 }))}
                  className={formErrors.requiredPoints ? 'ion-invalid ion-touched' : ''}
                  errorText={formErrors.requiredPoints}
                />
              </div>

              {formState.rewardType === 'discount' && (
                <div className="wizard-field-group">
                  <IonInput
                    fill="outline"
                    label="Valor de Descuento *"
                    labelPlacement="floating"
                    type="number"
                    value={formState.discountValue === null || formState.discountValue === 0 ? '' : formState.discountValue.toString()}
                    onIonInput={(e: CustomEvent<InputInputEventDetail>) => setFormState(p => ({ ...p, discountValue: parseFloat(e.detail.value!) || null }))}
                    className={formErrors.discountValue ? 'ion-invalid ion-touched' : ''}
                    errorText={formErrors.discountValue}
                  />
                </div>
              )}

              {formState.rewardType === 'free_product' && (
                <div className="wizard-field-group">
                  <IonInput
                    fill="outline"
                    label="ID del Producto Gratis *"
                    labelPlacement="floating"
                    type="number"
                    value={formState.freeProductId === null || formState.freeProductId === 0 ? '' : formState.freeProductId.toString()}
                    onIonInput={(e: CustomEvent<InputInputEventDetail>) => setFormState(p => ({ ...p, freeProductId: parseInt(e.detail.value!) || null }))}
                    className={formErrors.freeProductId ? 'ion-invalid ion-touched' : ''}
                    errorText={formErrors.freeProductId}
                  />
                </div>
              )}

              <div className="wizard-field-group">
                <IonItem lines="none" className="posrewardcatalogitem-toggle-item">
                  <IonLabel>Activo</IonLabel>
                  <IonToggle
                    slot="end"
                    checked={formState.isActive}
                    onIonChange={(e: CustomEvent<ToggleChangeEventDetail>) => setFormState(p => ({ ...p, isActive: e.detail.checked }))}
                  />
                </IonItem>
              </div>

              <div className="wizard-field-group">
                <IonTextarea
                  fill="outline"
                  label="Descripción"
                  labelPlacement="floating"
                  value={formState.description}
                  onIonInput={(e: CustomEvent<TextareaInputEventDetail>) => setFormState(p => ({ ...p, description: e.detail.value! }))}
                  rows={3}
                />
              </div>
            </div>
          </IonContent>
        </IonModal>

        {/* Delete Confirmation Alert */}
        <IonAlert
          isOpen={confirmDeleteAlert}
          onDidDismiss={() => setConfirmDeleteAlert(false)}
          header={'Confirmar Eliminación'}
          message={'¿Estás seguro de que quieres eliminar esta recompensa?'}
          buttons=[
            {
              text: 'Cancelar',
              role: 'cancel',
              cssClass: 'cancel-button',
            },
            {
              text: 'Eliminar',
              cssClass: 'delete-button',
              handler: handleDelete,
            },
          ]
        />
      </IonContent>
    </IonPage>
  );
};

export default PosRewardCatalogItemPage;
